		/** 
		 * Tests creating a new DSP.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a DSP");

			StringBuilder msg = new StringBuilder( "-- Failed to create a DSP" );

			try {            
				DSP entity = DSPService.getDSPInstance().createDSP( generateNewEntity() );
				thePrimaryKey = entity.getDSPId();
				LOGGER.info( "-- Successfully created a DSP with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a DSP. 
		 */
		public DSP testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created DSP" );

			DSP entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read DSP with primary key" );
			msg.append( thePrimaryKey );
			
			DSPFetchOneSummary fetchOneSummary = new DSPFetchOneSummary( thePrimaryKey );

			try {
				entity = DSPService.getDSPInstance().getDSP( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found DSP " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a DSP.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a DSP." );

			StringBuilder msg = new StringBuilder( "Failed to update a DSP : " );        
			DSP entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created DSP." );

				// for use later on...
				thePrimaryKey = entity.getDSPId();

				DSPService proxy = DSPService.getDSPInstance();            
				proxy.updateDSP( entity );   

				LOGGER.info( "-- Successfully saved DSP - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a DSP.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created DSP." );

			try{
			    DSP entity = testRead(); 
				DSPService.getDSPInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted DSP with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete DSP with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all DSPs.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of DSPs:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all DSP : " );        
			List<DSP> collection  = null;

			try {
				// call the static get method on the DSPService
				collection = DSPService.getDSPInstance().getAllDSP();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					DSP entity = null;            
					Iterator<DSP> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getDSPId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		DSPTest
		 */
		public DSPTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated DSP
		 * 
		 * @return DSP
		 */
		protected DSP generateNewEntity() {
			DSP entity = new DSP( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new HashSet<>() );
			
			return( entity );
		}

